import { fileURLToPath, URL } from "node:url"
import { defineConfig } from "vite"
import react from "@vitejs/plugin-react"
import tailwindcss from "@tailwindcss/vite"
import { VitePWA } from "vite-plugin-pwa"

const apiTarget = `http://127.0.0.1:${process.env.API_PORT || "8000"}`

export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
    VitePWA({
      registerType: "autoUpdate",
      includeAssets: ["favicon.svg", "icons/*.png", "seed/*.json", "proof.json"],
      manifest: {
        id: "/",
        name: "error404 — will my DB plan hold?",
        short_name: "error404",
        description:
          "Share a Deutsche Bahn connection and see the probability your plan fails, plus what to do about it.",
        start_url: "/",
        scope: "/",
        display: "standalone",
        orientation: "any",
        background_color: "#07070c",
        theme_color: "#07070c",
        icons: [
          { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
          { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
          {
            src: "/icons/icon-maskable-512.png",
            sizes: "512x512",
            type: "image/png",
            purpose: "maskable",
          },
        ],
        share_target: {
          action: "/share",
          method: "GET",
          params: { title: "title", text: "text", url: "url" },
        },
      } as Record<string, unknown>,
      workbox: {
        globPatterns: ["**/*.{js,css,html,svg,png,jpg,json,woff2}"],
        maximumFileSizeToCacheInBytes: 4 * 1024 * 1024,
        navigateFallback: "/index.html",
        navigateFallbackDenylist: [/^\/api\//],
        runtimeCaching: [
          {
            urlPattern: /^https:\/\/[abcd]\.basemaps\.cartocdn\.com\/.*/i,
            handler: "CacheFirst",
            options: {
              cacheName: "tiles",
              expiration: { maxEntries: 3000, maxAgeSeconds: 7 * 24 * 3600 },
              cacheableResponse: { statuses: [0, 200] },
            },
          },
          {
            urlPattern: /\/api\/(seed\/demo|causes)/,
            handler: "NetworkFirst",
            options: { cacheName: "api-seed", networkTimeoutSeconds: 3 },
          },
        ],
      },
      devOptions: { enabled: false },
    }),
  ],
  resolve: { alias: { "@": fileURLToPath(new URL("./src", import.meta.url)) } },
  server: {
    host: "127.0.0.1",
    port: 5173,
    strictPort: true,
    proxy: { "/api": { target: apiTarget, changeOrigin: true } },
  },
  preview: {
    host: "127.0.0.1",
    proxy: { "/api": { target: apiTarget, changeOrigin: true } },
  },
  build: { sourcemap: false, outDir: "dist" },
})

// Types from team-setup/state/03-contract-freeze/contract.md, plus additive
// optional fields the app uses (lat/lon, distributions, leave-home time).

export type Station = {
  evaNumber: string
  name: string
  lat?: number
  lon?: number
}

export type Leg = {
  trainId: string // e.g. "RB 16"
  trainNumber?: string
  from: Station
  to: Station
  plannedDeparture: string // ISO 8601 with offset
  plannedArrival: string
  transferMinutes?: number // planned transfer to the next leg
}

export type Journey = {
  id: string
  legs: Leg[]
  source: "db-share" | "manual" | "seed"
}

export type Confidence = "low" | "medium" | "high"

export type Explained<T> = {
  value: T
  reasoning: string
  sources: string[]
  confidence: Confidence
}

export type DelayDistribution = {
  bins: string[] // e.g. ["≤5", "5–15", "15–30", ">30", "cancelled"]
  probs: number[]
}

export type LegDelay = {
  trainId: string
  expectedDelayMinutes: Explained<number>
  missProbability: Explained<number> // 0..1, chance this transfer breaks
  distribution?: DelayDistribution
  quantiles?: { p10: number; p50: number; p90: number }
  pCancel?: number
  // Full per-minute pmf when the backend provides it; used by the buffer slider.
  probs?: number[]
}

export type Prediction = {
  journeyId: string
  legs: LegDelay[]
  planFailProbability: Explained<number>
  modelId: string
}

export type Verdict = "good" | "add-buffer" | "take-alternative"

export type Recommendation = {
  verdict: Verdict
  advice: Explained<string>
  bufferMinutes?: number
  alternative?: Journey
  leaveHomeBy?: string
  chosenDeparture?: string
}

export type RerouteOption = {
  journey: Journey
  planFailProbability: Explained<number>
  arrivalDelayMinutes: number
  label: string
}

export type Reroute = {
  station: Station
  options: RerouteOption[]
}

export type CauseFamilies = {
  works: number
  weather: number
  technical: number
  knock_on: number
  staff: number
  external: number
  unattributed: number
}

export type Causes = {
  station: Station
  attributionRate: number
  families: CauseFamilies
  top: { code: number; text: string; share: number }[]
  sparkline7d: { date: string; meanDelayMin: number }[]
  source: string
}

export type Proof = {
  metric: string
  label: string
  lowerIsBetter: boolean
  n: number
  split: string
  models: { name: string; value: number; highlight?: boolean }[]
}

// Port of app/agents/src/features/db_delay/trip/connection.py.
// A change works when both trains run and
//   arrival delay - departure delay <= planned buffer - minimum transfer.
// Trains are treated as independent (optimistic when one disruption hits both).

import type { Journey, LegDelay, Prediction } from "./contract"

export type TrainForecast = { probs: number[]; pCancel?: number }

export const LATE_MINUTES = 6
export const MIN_TRANSFER_MINUTES = 5

export function normalise(probs: number[]): Float64Array {
  let total = 0
  for (const p of probs) total += p
  if (!(total > 0)) throw new Error("delay distribution has no mass")
  return Float64Array.from(probs, (p) => p / total)
}

/** P(both run and A - D <= floor(buffer - minTransfer)). */
export function changeProbability(
  arriving: TrainForecast,
  departing: TrainForecast,
  plannedBuffer: number,
  minTransfer: number,
): number {
  const a = normalise(arriving.probs)
  const d = normalise(departing.probs)
  const slack = Math.floor(plannedBuffer - minTransfer)
  // tail[k] = P(D >= k)
  const tail = new Float64Array(d.length + 1)
  for (let k = d.length - 1; k >= 0; k--) tail[k] = tail[k + 1] + d[k]
  let made = 0
  for (let i = 0; i < a.length; i++) {
    const k = i - slack // need D >= i - slack
    made += a[i] * (k <= 0 ? 1 : k >= d.length ? 0 : tail[k])
  }
  return (1 - (arriving.pCancel ?? 0)) * (1 - (departing.pCancel ?? 0)) * made
}

export function journeyProbability(
  changes: [TrainForecast, TrainForecast, number, number][],
  finalArrival?: TrainForecast,
  arrivalSlack?: number,
) {
  const perChange = changes.map(([a, d, b, m]) => changeProbability(a, d, b, m))
  let success = perChange.reduce((p, x) => p * x, 1)
  if (finalArrival && arrivalSlack != null) {
    const pmf = normalise(finalArrival.probs)
    let onTime = 0
    for (let k = 0; k <= Math.floor(arrivalSlack) && k < pmf.length; k++) onTime += pmf[k]
    success *= (1 - (finalArrival.pCancel ?? 0)) * onTime
  }
  return { changeProbabilities: perChange, planSuccess: success, planFail: 1 - success }
}

export function point(minutes: number, size = 240, pCancel = 0): TrainForecast {
  const probs = new Array<number>(size).fill(0)
  probs[Math.min(minutes, size - 1)] = 1
  return { probs, pCancel }
}

export function quantile(probs: number[], q: number): number {
  const p = normalise(probs)
  let c = 0
  for (let k = 0; k < p.length; k++) {
    c += p[k]
    if (c >= q) return k
  }
  return p.length - 1
}

/** Geometric pmf whose median lands on `median` minutes (mirrors the backend mock). */
export function geometricPmf(median: number, size = 240): number[] {
  const q = Math.pow(0.5, 1 / (Math.max(median, 0) + 1))
  const probs = new Array<number>(size)
  for (let k = 0; k < size; k++) probs[k] = (1 - q) * Math.pow(q, k)
  return probs
}

function forecastOf(leg: LegDelay): TrainForecast {
  const probs = leg.probs && leg.probs.length ? leg.probs : geometricPmf(leg.expectedDelayMinutes.value)
  return { probs, pCancel: leg.pCancel ?? 0 }
}

function minutesBetween(a: string, b: string): number {
  return Math.round((new Date(b).getTime() - new Date(a).getTime()) / 60000)
}

export function transferBuffer(journey: Journey, i: number): number {
  const leg = journey.legs[i]
  const next = journey.legs[i + 1]
  if (!next) return 0
  return leg.transferMinutes ?? minutesBetween(leg.plannedArrival, next.plannedDeparture)
}

/**
 * Re-chain a prediction in the browser with extra minutes added at one transfer
 * (or every transfer when index is -1). Used by the buffer slider.
 */
export function rechain(
  journey: Journey,
  prediction: Prediction,
  extraMinutes: number,
  atTransfer = -1,
  minTransfer = MIN_TRANSFER_MINUTES,
): { legs: number[]; planFail: number } {
  const changes: [TrainForecast, TrainForecast, number, number][] = []
  for (let i = 0; i < journey.legs.length - 1; i++) {
    const arr = forecastOf(prediction.legs[i])
    const depLeg = prediction.legs[i + 1]
    const dep: TrainForecast = { probs: geometricPmf(depLeg.expectedDelayMinutes.value * 0.4), pCancel: depLeg.pCancel ?? 0 }
    const extra = atTransfer === -1 || atTransfer === i ? extraMinutes : 0
    changes.push([arr, dep, transferBuffer(journey, i) + extra, minTransfer])
  }
  const r = journeyProbability(changes)
  const legs = r.changeProbabilities.map((p) => 1 - p)
  legs.push(0)
  return { legs, planFail: r.planFail }
}

import type { Journey, Station } from "./contract"
import raw from "./stations.json"

export type StationEntry = { name: string; evaNumber: string; lat: number; lon: number; aliases: string[] }

export const STATIONS: StationEntry[] = raw as StationEntry[]

export function normaliseName(s: string): string {
  return s
    .toLowerCase()
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/ß/g, "ss")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/hauptbahnhof/g, "hbf")
    .replace(/[()\-.,/]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
}

const byEva = new Map<string, StationEntry>()
const byName = new Map<string, StationEntry>()
for (const st of STATIONS) {
  byEva.set(st.evaNumber, st)
  byName.set(normaliseName(st.name), st)
  for (const a of st.aliases) byName.set(normaliseName(a), st)
}

export function lookupStation(q: { evaNumber?: string; name?: string }): StationEntry | undefined {
  if (q.evaNumber && byEva.has(q.evaNumber)) return byEva.get(q.evaNumber)
  if (!q.name) return undefined
  const n = normaliseName(q.name)
  if (byName.has(n)) return byName.get(n)
  const stripped = n.replace(/\b(hbf|hb)\b/g, "").trim()
  for (const [k, v] of byName) if (k.replace(/\b(hbf|hb)\b/g, "").trim() === stripped) return v
  for (const [k, v] of byName) if (k.startsWith(n) || n.startsWith(k)) return v
  return undefined
}

export function searchStations(q: string, limit = 8): StationEntry[] {
  const n = normaliseName(q)
  if (!n) return []
  const seen = new Set<string>()
  const out: StationEntry[] = []
  for (const st of STATIONS) {
    const hay = [st.name, ...st.aliases].map(normaliseName)
    if (hay.some((h) => h.includes(n)) && !seen.has(st.evaNumber)) {
      seen.add(st.evaNumber)
      out.push(st)
      if (out.length >= limit) break
    }
  }
  return out
}

export function withCoords(station: Station): Station {
  if (station.lat != null && station.lon != null) return station
  const hit = lookupStation(station)
  return hit ? { ...station, evaNumber: station.evaNumber || hit.evaNumber, lat: hit.lat, lon: hit.lon } : station
}

export function hydrateCoords(journey: Journey): Journey {
  return { ...journey, legs: journey.legs.map((l) => ({ ...l, from: withCoords(l.from), to: withCoords(l.to) })) }
}

import type { Journey, Leg } from "./contract"

export type LngLat = [number, number]

export function legLine(leg: Leg): LngLat[] | null {
  if (leg.from.lon == null || leg.from.lat == null || leg.to.lon == null || leg.to.lat == null) return null
  return [
    [leg.from.lon, leg.from.lat],
    [leg.to.lon, leg.to.lat],
  ]
}

export function journeyBounds(journey: Journey): [LngLat, LngLat] | null {
  let minLon = Infinity, minLat = Infinity, maxLon = -Infinity, maxLat = -Infinity
  for (const leg of journey.legs) {
    for (const s of [leg.from, leg.to]) {
      if (s.lon == null || s.lat == null) continue
      minLon = Math.min(minLon, s.lon); maxLon = Math.max(maxLon, s.lon)
      minLat = Math.min(minLat, s.lat); maxLat = Math.max(maxLat, s.lat)
    }
  }
  if (!isFinite(minLon)) return null
  return [[minLon, minLat], [maxLon, maxLat]]
}

export function riskLevel(p: number): "low" | "mid" | "high" {
  if (p < 0.15) return "low"
  if (p < 0.4) return "mid"
  return "high"
}

export const RISK_COLOUR = { low: "#34d399", mid: "#fbbf24", high: "#f87171", none: "#8b8bff" } as const

export function riskColour(p: number | undefined): string {
  if (p == null) return RISK_COLOUR.none
  return RISK_COLOUR[riskLevel(p)]
}

export function fmtTime(iso: string): string {
  const d = new Date(iso)
  if (isNaN(d.getTime())) return "--:--"
  return d.toLocaleTimeString("de-DE", { hour: "2-digit", minute: "2-digit", timeZone: "Europe/Berlin" })
}

export function fmtDate(iso: string): string {
  const d = new Date(iso)
  if (isNaN(d.getTime())) return ""
  return d.toLocaleDateString("en-GB", { weekday: "short", day: "2-digit", month: "2-digit", year: "numeric", timeZone: "Europe/Berlin" })
}

export function pct(p: number): string {
  return `${Math.round(p * 100)}%`
}

import type { Causes, Journey, Prediction, Recommendation, Reroute } from "./contract"

const TIMEOUT_MS = 8000

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, {
    ...init,
    headers: { "content-type": "application/json", ...(init?.headers || {}) },
    signal: AbortSignal.timeout(TIMEOUT_MS),
  })
  if (!res.ok) {
    let msg = `${res.status} ${res.statusText}`
    try {
      const body = await res.json()
      if (body?.error) msg = body.error
    } catch {
      /* ignore */
    }
    throw new ApiError(res.status, msg)
  }
  return (await res.json()) as T
}

export class ApiError extends Error {
  status: number
  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

const post = (body: unknown) => ({ method: "POST", body: JSON.stringify(body) })

export const api = {
  health: () => request<{ ok: boolean }>("/api/health"),
  seedDemo: () => request<Journey>("/api/seed/demo"),
  parseJourney: (text: string) => request<Journey>("/api/journeys/parse", post({ text })),
  predict: (journey: Journey) => request<Prediction>("/api/predict", post(journey)),
  recommend: (journey: Journey, prediction: Prediction, doorToStationMin?: number, acceptableRisk?: number) =>
    request<Recommendation>("/api/recommend", post({ journey, prediction, doorToStationMin, acceptableRisk })),
  reroute: (journey: Journey, missedLegIndex: number) =>
    request<Reroute>("/api/reroute", post({ journey, missedLegIndex })),
  causes: (evaNumber: string, name?: string) =>
    request<Causes>(`/api/causes?eva=${encodeURIComponent(evaNumber)}${name ? `&station=${encodeURIComponent(name)}` : ""}`),
}

export async function loadFixture<T>(name: string): Promise<T> {
  const res = await fetch(`/seed/${name}.json`, { signal: AbortSignal.timeout(TIMEOUT_MS) })
  if (!res.ok) throw new Error(`fixture ${name} missing`)
  return (await res.json()) as T
}

import { useEffect, useState } from "react"

function readMotionOff(): boolean {
  try {
    const q = new URLSearchParams(location.search)
    if (q.get("motion") === "0") return true
    if (document.documentElement.dataset.motion === "0") return true
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches
  } catch {
    return false
  }
}

let listeners = new Set<() => void>()
export function toggleMotion() {
  const off = document.documentElement.dataset.motion === "0"
  if (off) delete document.documentElement.dataset.motion
  else document.documentElement.dataset.motion = "0"
  listeners.forEach((l) => l())
}

export function useReducedMotion(): boolean {
  const [off, setOff] = useState(readMotionOff)
  useEffect(() => {
    const update = () => setOff(readMotionOff())
    listeners.add(update)
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    mq.addEventListener("change", update)
    return () => {
      listeners.delete(update)
      mq.removeEventListener("change", update)
    }
  }, [])
  return off
}

export function motionOff(): boolean {
  return readMotionOff()
}

export const DUR = { fly: 2400, leg: 700, count: 1200 } as const

import { createContext, useCallback, useContext, useMemo, useReducer, type ReactNode } from "react"
import { api, loadFixture } from "./api"
import type { Causes, Journey, Prediction, Recommendation, Reroute, Station } from "./contract"
import { hydrateCoords } from "./stations"

export type Tab = "plan" | "forecast" | "advice" | "causes" | "evidence"
export type Stage = "idle" | "parsing" | "journey" | "predicting" | "predicted" | "recommending" | "done" | "error"

export type State = {
  tab: Tab
  stage: Stage
  sharedText?: string
  journey?: Journey
  prediction?: Prediction
  recommendation?: Recommendation
  reroute?: Reroute
  missedLeg?: number
  causes?: Causes
  causesFor?: string
  error?: string
  offline: boolean
  selectedLeg: number | null
  bufferExtra: number
  doorToStationMin: number
  acceptableRisk: number
  overlay: "none" | "alternative" | "reroute"
  rerouteChoice: number
  stageMode: boolean
  stageStep: number
  busy: boolean
}

type Action =
  | { type: "tab"; tab: Tab }
  | { type: "stage"; stage: Stage }
  | { type: "share"; text: string }
  | { type: "journey"; journey: Journey }
  | { type: "prediction"; prediction: Prediction }
  | { type: "recommendation"; recommendation: Recommendation }
  | { type: "reroute"; reroute: Reroute; missedLeg: number }
  | { type: "causes"; causes: Causes; causesFor: string }
  | { type: "error"; error: string }
  | { type: "offline"; offline: boolean }
  | { type: "selectLeg"; index: number | null }
  | { type: "buffer"; minutes: number }
  | { type: "door"; minutes: number }
  | { type: "risk"; risk: number }
  | { type: "overlay"; overlay: State["overlay"] }
  | { type: "rerouteChoice"; index: number }
  | { type: "stageMode"; on: boolean }
  | { type: "stageStep"; step: number }
  | { type: "busy"; busy: boolean }
  | { type: "reset" }

const initial: State = {
  tab: "plan",
  stage: "idle",
  offline: false,
  selectedLeg: null,
  bufferExtra: 0,
  doorToStationMin: 20,
  acceptableRisk: 0.15,
  overlay: "none",
  rerouteChoice: 0,
  stageMode: false,
  stageStep: 0,
  busy: false,
}

function reducer(s: State, a: Action): State {
  switch (a.type) {
    case "tab": return { ...s, tab: a.tab }
    case "stage": return { ...s, stage: a.stage }
    case "share": return { ...s, sharedText: a.text, stage: "parsing", error: undefined }
    case "journey": return { ...s, journey: a.journey, prediction: undefined, recommendation: undefined, reroute: undefined, missedLeg: undefined, overlay: "none", bufferExtra: 0, selectedLeg: null, stage: "journey", error: undefined }
    case "prediction": return { ...s, prediction: a.prediction, stage: "predicted" }
    case "recommendation": return { ...s, recommendation: a.recommendation, stage: "done" }
    case "reroute": return { ...s, reroute: a.reroute, missedLeg: a.missedLeg, overlay: "reroute", rerouteChoice: 0 }
    case "causes": return { ...s, causes: a.causes, causesFor: a.causesFor }
    case "error": return { ...s, error: a.error, stage: "error", busy: false }
    case "offline": return { ...s, offline: a.offline }
    case "selectLeg": return { ...s, selectedLeg: a.index }
    case "buffer": return { ...s, bufferExtra: a.minutes }
    case "door": return { ...s, doorToStationMin: a.minutes }
    case "risk": return { ...s, acceptableRisk: a.risk }
    case "overlay": return { ...s, overlay: a.overlay }
    case "rerouteChoice": return { ...s, rerouteChoice: a.index }
    case "stageMode": return { ...s, stageMode: a.on, stageStep: a.on ? s.stageStep : 0 }
    case "stageStep": return { ...s, stageStep: a.step }
    case "busy": return { ...s, busy: a.busy }
    case "reset": return { ...initial, offline: s.offline, stageMode: s.stageMode }
  }
}

type Actions = {
  dispatch: (a: Action) => void
  runFromText: (text: string) => Promise<void>
  runFromSeed: () => Promise<void>
  runJourney: (journey: Journey) => Promise<void>
  refreshRecommendation: (doorToStationMin?: number, acceptableRisk?: number) => Promise<void>
  fetchReroute: (missedLeg: number) => Promise<void>
  fetchCauses: (station: Station) => Promise<void>
}

const Ctx = createContext<(State & Actions) | null>(null)

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms))

export function StoreProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(reducer, initial)

  const pipeline = useCallback(
    async (journey: Journey, opts?: { door?: number; risk?: number }) => {
      const j = hydrateCoords(journey)
      dispatch({ type: "journey", journey: j })
      dispatch({ type: "busy", busy: true })
      let offline = false
      let prediction: Prediction
      dispatch({ type: "stage", stage: "predicting" })
      try {
        prediction = await api.predict(j)
      } catch {
        offline = true
        prediction = await loadFixture<Prediction>("prediction")
        prediction = { ...prediction, journeyId: j.id }
      }
      await sleep(250)
      dispatch({ type: "prediction", prediction })
      dispatch({ type: "stage", stage: "recommending" })
      let recommendation: Recommendation
      try {
        if (offline) throw new Error("offline")
        recommendation = await api.recommend(j, prediction, opts?.door, opts?.risk)
      } catch {
        offline = true
        recommendation = await loadFixture<Recommendation>("recommendation")
      }
      if (recommendation.alternative) recommendation = { ...recommendation, alternative: hydrateCoords(recommendation.alternative) }
      dispatch({ type: "offline", offline })
      dispatch({ type: "recommendation", recommendation })
      dispatch({ type: "busy", busy: false })
    },
    [],
  )

  const runJourney = useCallback((journey: Journey) => pipeline(journey), [pipeline])

  const runFromText = useCallback(
    async (text: string) => {
      dispatch({ type: "share", text })
      dispatch({ type: "busy", busy: true })
      try {
        const journey = await api.parseJourney(text)
        await pipeline(journey)
      } catch (e) {
        const err = e as { status?: number; message?: string }
        if (err.status === 400 || err.status === 422) {
          dispatch({ type: "error", error: err.message || "Could not find a connection in that text." })
          return
        }
        // Backend unreachable: fall back to the seed so the app still works.
        dispatch({ type: "offline", offline: true })
        try {
          const journey = await loadFixture<Journey>("journey")
          await pipeline(journey)
        } catch {
          dispatch({ type: "error", error: "The forecast service is unreachable and no offline seed is bundled." })
        }
      }
    },
    [pipeline],
  )

  const runFromSeed = useCallback(async () => {
    dispatch({ type: "busy", busy: true })
    let journey: Journey
    try {
      journey = await api.seedDemo()
    } catch {
      dispatch({ type: "offline", offline: true })
      journey = await loadFixture<Journey>("journey")
    }
    await pipeline(journey)
  }, [pipeline])

  const refreshRecommendation = useCallback(
    async (door?: number, risk?: number) => {
      if (!state.journey || !state.prediction) return
      if (door != null) dispatch({ type: "door", minutes: door })
      if (risk != null) dispatch({ type: "risk", risk })
      try {
        let rec = await api.recommend(state.journey, state.prediction, door ?? state.doorToStationMin, risk ?? state.acceptableRisk)
        if (rec.alternative) rec = { ...rec, alternative: hydrateCoords(rec.alternative) }
        dispatch({ type: "recommendation", recommendation: rec })
      } catch {
        /* keep the current recommendation; LeaveHomeBy computes locally */
      }
    },
    [state.journey, state.prediction, state.doorToStationMin, state.acceptableRisk],
  )

  const fetchReroute = useCallback(
    async (missedLeg: number) => {
      if (!state.journey) return
      let reroute: Reroute
      try {
        reroute = await api.reroute(state.journey, missedLeg)
      } catch {
        reroute = await loadFixture<Reroute>("reroute")
      }
      reroute = { ...reroute, options: reroute.options.map((o) => ({ ...o, journey: hydrateCoords(o.journey) })) }
      dispatch({ type: "reroute", reroute, missedLeg })
    },
    [state.journey],
  )

  const fetchCauses = useCallback(
    async (station: Station) => {
      const key = station.evaNumber || station.name
      if (state.causesFor === key && state.causes) return
      let causes: Causes
      try {
        causes = await api.causes(station.evaNumber, station.name)
      } catch {
        causes = await loadFixture<Causes>("causes")
        causes = { ...causes, station }
      }
      dispatch({ type: "causes", causes, causesFor: key })
    },
    [state.causesFor, state.causes],
  )

  const value = useMemo(
    () => ({ ...state, dispatch, runFromText, runFromSeed, runJourney, refreshRecommendation, fetchReroute, fetchCauses }),
    [state, runFromText, runFromSeed, runJourney, refreshRecommendation, fetchReroute, fetchCauses],
  )
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>
}

export function useStore() {
  const v = useContext(Ctx)
  if (!v) throw new Error("useStore outside StoreProvider")
  return v
}

