  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.45);
}

.panel {
  position: absolute;
  z-index: 20;
  display: flex;
  flex-direction: column;
  left: 0;
  right: 0;
  bottom: 0;
  max-height: var(--sheet-h);
  border-radius: 22px 22px 0 0;
  padding-bottom: env(safe-area-inset-bottom);
}
@media (min-width: 1024px) {
  .panel {
    left: auto;
    top: 16px;
    right: 16px;
    bottom: 16px;
    width: var(--panel-w);
    max-height: none;
    border-radius: 22px;
  }
}
.panel-scroll {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.15) transparent;
}

.brand {
  position: absolute;
  z-index: 20;
  top: max(12px, env(safe-area-inset-top));
  left: 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: none;
}
.brand > * {
  pointer-events: auto;
}

.headline-number {
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.04em;
  line-height: 0.95;
}

.tabbar button[aria-selected="true"] {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.leg-card[data-active="true"] {
  border-color: rgba(139, 139, 255, 0.7);
  box-shadow: 0 0 0 1px rgba(139, 139, 255, 0.4);
}

.stage-dots {
  position: absolute;
  z-index: 30;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
}
.stage-dots i {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.25);
}
.stage-dots i[data-on="true"] {
  background: #fff;
  width: 22px;
}

@keyframes pulse-ring {
  0% { transform: scale(0.9); opacity: 0.8; }
  100% { transform: scale(1.8); opacity: 0; }
}
.pulse {
  animation: pulse-ring 1.6s ease-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}
html[data-motion="0"] *,
html[data-motion="0"] *::before,
html[data-motion="0"] *::after {
  animation-duration: 0.001ms !important;
  transition-duration: 0.001ms !important;
}

import { Component, type ReactNode } from "react"
import { createRoot } from "react-dom/client"
import { registerSW } from "virtual:pwa-register"
import { StoreProvider } from "@/lib/store"
import App from "./App"
import "./index.css"

class ErrorBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false }
  static getDerivedStateFromError() {
    return { failed: true }
  }
  render() {
    if (this.state.failed)
      return (
        <main className="flex h-full flex-col items-center justify-center gap-4 p-8 text-center">
          <h1 className="text-2xl font-semibold">Something broke on this screen.</h1>
          <p className="text-muted-foreground">Reload to start again. Nothing was saved.</p>
          <button className="rounded-md bg-primary px-4 py-2 text-white" onClick={() => location.reload()}>
            Reload
          </button>
        </main>
      )
    return this.props.children
  }
}

registerSW({ immediate: true })

createRoot(document.getElementById("root")!).render(
  <ErrorBoundary>
    <StoreProvider>
      <App />
    </StoreProvider>
  </ErrorBoundary>,
)

