import type maplibregl from "maplibre-gl"
import type { Journey, Leg, Station } from "@/lib/contract"
import { journeyBounds, type LngLat } from "@/lib/geo"
import { DUR, motionOff } from "@/lib/motion"

export const HOME = { center: [10.5, 48] as LngLat, zoom: 1.35, pitch: 0, bearing: 0 }

/** Padding that keeps the route clear of the overlay panel. */
export function panelPadding(): { top: number; bottom: number; left: number; right: number } {
  const w = window.innerWidth
  const h = window.innerHeight
  if (w >= 1024) {
    const panel = Math.min(w * 0.36, Math.max(380, Math.min(520, w * 0.32)))
    return { top: 90, bottom: 60, left: 60, right: panel + 48 }
  }
  return { top: 80, bottom: Math.round(h * 0.55), left: 36, right: 36 }
}

const dur = (ms: number) => (motionOff() ? 0 : ms)

export function goHome(map: maplibregl.Map) {
  map.flyTo({ ...HOME, duration: dur(DUR.fly), essential: true })
}

export function fitJourney(map: maplibregl.Map, journeys: Journey[], opts: { maxZoom?: number; duration?: number } = {}) {
  let minLon = Infinity, minLat = Infinity, maxLon = -Infinity, maxLat = -Infinity
  for (const j of journeys) {
    const b = journeyBounds(j)
    if (!b) continue
    minLon = Math.min(minLon, b[0][0]); minLat = Math.min(minLat, b[0][1])
    maxLon = Math.max(maxLon, b[1][0]); maxLat = Math.max(maxLat, b[1][1])
  }
  if (!isFinite(minLon)) return
  // Give very short routes some air so the fit does not zoom to street level.
  const padDeg = 0.02
  map.fitBounds(
    [
      [minLon - padDeg, minLat - padDeg],
      [maxLon + padDeg, maxLat + padDeg],
    ],
    { padding: panelPadding(), duration: opts.duration ?? dur(DUR.fly), maxZoom: opts.maxZoom ?? 10.5, pitch: 0, bearing: 0, essential: true },
  )
}

export function flyToLeg(map: maplibregl.Map, leg: Leg) {
  if (leg.from.lon == null || leg.to.lon == null || leg.from.lat == null || leg.to.lat == null) return
  const padDeg = 0.03
  map.fitBounds(
    [
      [Math.min(leg.from.lon, leg.to.lon) - padDeg, Math.min(leg.from.lat, leg.to.lat) - padDeg],
      [Math.max(leg.from.lon, leg.to.lon) + padDeg, Math.max(leg.from.lat, leg.to.lat) + padDeg],
    ],
    { padding: panelPadding(), duration: dur(1600), maxZoom: 11.5, pitch: 35, essential: true },
  )
}

export function flyToStation(map: maplibregl.Map, station: Station, zoom = 11) {
  if (station.lon == null || station.lat == null) return
  const pad = panelPadding()
  map.flyTo({
    center: [station.lon, station.lat],
    zoom,
    pitch: 50,
    bearing: -15,
    duration: dur(1800),
    essential: true,
    padding: pad,
  })
}

/** Slow idle rotation of the globe until the user touches it. */
export function startIdleSpin(map: maplibregl.Map): () => void {
  if (motionOff()) return () => {}
  let raf = 0
  let stopped = false
  const stop = () => {
    stopped = true
    cancelAnimationFrame(raf)
  }
  const tick = () => {
    if (stopped) return
    if (!map.isMoving()) {
      const c = map.getCenter()
      map.jumpTo({ center: [c.lng + 0.035, c.lat] })
    }
    raf = requestAnimationFrame(tick)
  }
  raf = requestAnimationFrame(tick)
  const onInteract = () => stop()
  map.on("mousedown", onInteract)
  map.on("touchstart", onInteract)
  map.on("wheel", onInteract)
  return () => {
    stop()
    map.off("mousedown", onInteract)
    map.off("touchstart", onInteract)
    map.off("wheel", onInteract)
  }
}

import maplibregl from "maplibre-gl"
import type { Journey } from "@/lib/contract"
import { legLine, RISK_COLOUR } from "@/lib/geo"
import { DUR, motionOff } from "@/lib/motion"

export type RouteKind = "main" | "alt"

type Handles = {
  markers: maplibregl.Marker[]
  layerIds: string[]
  sourceIds: string[]
  anim: number
}

const registry = new WeakMap<maplibregl.Map, Record<RouteKind, Handles>>()

function handles(map: maplibregl.Map, kind: RouteKind): Handles {
  let r = registry.get(map)
  if (!r) {
    r = { main: { markers: [], layerIds: [], sourceIds: [], anim: 0 }, alt: { markers: [], layerIds: [], sourceIds: [], anim: 0 } }
    registry.set(map, r)
  }
  return r[kind]
}

export function clearRoute(map: maplibregl.Map, kind: RouteKind) {
  const h = handles(map, kind)
  cancelAnimationFrame(h.anim)
  for (const id of h.layerIds) if (map.getLayer(id)) map.removeLayer(id)
  for (const id of h.sourceIds) if (map.getSource(id)) map.removeSource(id)
  for (const m of h.markers) m.remove()
  h.layerIds = []
  h.sourceIds = []
  h.markers = []
}

function gradient(colour: string, t: number): maplibregl.ExpressionSpecification {
  const stop = Math.max(0, Math.min(1, t))
  const edge = Math.min(1, stop + 0.0005)
  return ["interpolate", ["linear"], ["line-progress"], 0, colour, stop, colour, edge, "rgba(0,0,0,0)", 1, "rgba(0,0,0,0)"]
}

export type DrawOptions = {
  colours?: (string | undefined)[] // per leg
  dashed?: boolean
  animate?: boolean
  onStationClick?: (legIndex: number, end: "from" | "to") => void
  labels?: boolean
  width?: number
}

/** Draw a journey's legs as glowing lines plus station markers. Idempotent per kind. */
export function drawRoute(map: maplibregl.Map, kind: RouteKind, journey: Journey, opts: DrawOptions = {}) {
  clearRoute(map, kind)
  const h = handles(map, kind)
  const base = kind === "main" ? RISK_COLOUR.none : "#a7f3d0"
  const width = opts.width ?? (kind === "main" ? 4.5 : 3.5)
  const animate = (opts.animate ?? true) && !motionOff()

  journey.legs.forEach((leg, i) => {
    const line = legLine(leg)
    if (!line) return
    const colour = opts.colours?.[i] ?? base
    const sourceId = `route-${kind}-${i}`
    map.addSource(sourceId, {
      type: "geojson",
      lineMetrics: true,
      data: { type: "Feature", properties: { leg: i }, geometry: { type: "LineString", coordinates: line } },
    })
    h.sourceIds.push(sourceId)
    const glowId = `${sourceId}-glow`
    const lineId = `${sourceId}-line`
    map.addLayer({
      id: glowId,
      type: "line",
      source: sourceId,
      layout: { "line-cap": "round", "line-join": "round" },
      paint: { "line-width": width * 3, "line-opacity": 0.22, "line-blur": 6, "line-gradient": gradient(colour, animate ? 0 : 1) },
    })
    map.addLayer({
      id: lineId,
      type: "line",
      source: sourceId,
      layout: { "line-cap": "round", "line-join": "round" },
      paint: {
        "line-width": width,
        "line-opacity": 0.95,
        ...(opts.dashed ? { "line-dasharray": [1.5, 1.5] } : {}),
        "line-gradient": gradient(colour, animate ? 0 : 1),
      },
    })
    h.layerIds.push(glowId, lineId)
  })

  // Station markers: HTML so they work without glyph fonts and offline.
  const seen = new Set<string>()
  journey.legs.forEach((leg, i) => {
    const ends: ["from" | "to", typeof leg.from][] = [["from", leg.from], ["to", leg.to]]
    for (const [end, st] of ends) {
      if (st.lon == null || st.lat == null) continue
      const key = `${st.evaNumber || st.name}`
      if (seen.has(key)) continue
      seen.add(key)
      const el = document.createElement("button")
      el.type = "button"
      el.className = "station-marker"
      el.setAttribute("aria-label", st.name)
      const colour = end === "to" ? (opts.colours?.[i] ?? base) : (opts.colours?.[i - 1] ?? base)
      el.innerHTML = `<span class="dot" style="--c:${colour}"></span>${opts.labels === false ? "" : `<span class="label">${st.name}</span>`}`
      el.addEventListener("click", (e) => {
        e.stopPropagation()
        opts.onStationClick?.(i, end)
      })
      const m = new maplibregl.Marker({ element: el, anchor: "left", offset: [10, 0] }).setLngLat([st.lon, st.lat]).addTo(map)
      h.markers.push(m)
    }
  })

  if (animate) animateDraw(map, kind, journey, opts.colours ?? [], base)
}

function animateDraw(map: maplibregl.Map, kind: RouteKind, journey: Journey, colours: (string | undefined)[], base: string) {
  const h = handles(map, kind)
  const legs = journey.legs.map((_, i) => i).filter((i) => legLine(journey.legs[i]))
  const per = DUR.leg
  const start = performance.now()
  const step = (now: number) => {
    const elapsed = now - start
    legs.forEach((i, order) => {
      const t = Math.max(0, Math.min(1, (elapsed - order * per) / per))
      const colour = colours[i] ?? base
      const sourceId = `route-${kind}-${i}`
      for (const suffix of ["glow", "line"]) {
        const id = `${sourceId}-${suffix}`
        if (map.getLayer(id)) map.setPaintProperty(id, "line-gradient", gradient(colour, t))
      }
    })
    if (elapsed < legs.length * per) h.anim = requestAnimationFrame(step)
  }
  h.anim = requestAnimationFrame(step)
}

/** Recolour an existing route (e.g. once the forecast arrives) without redrawing. */
export function recolourRoute(map: maplibregl.Map, kind: RouteKind, journey: Journey, colours: (string | undefined)[]) {
  const h = handles(map, kind)
  cancelAnimationFrame(h.anim)
  journey.legs.forEach((_, i) => {
    const colour = colours[i] ?? RISK_COLOUR.none
    for (const suffix of ["glow", "line"]) {
      const id = `route-${kind}-${i}-${suffix}`
      if (map.getLayer(id)) map.setPaintProperty(id, "line-gradient", gradient(colour, 1))
    }
  })
  h.markers.forEach((m) => {
    const el = m.getElement()
    const dot = el.querySelector<HTMLElement>(".dot")
    if (!dot) return
    // Marker order mirrors leg iteration: recompute colour by matching label to the leg ends.
    const name = el.getAttribute("aria-label")
    const idx = journey.legs.findIndex((l) => l.to.name === name)
    if (idx >= 0) dot.style.setProperty("--c", colours[idx] ?? RISK_COLOUR.none)
  })
}

