import { useEffect, useState } from "react"

export type Route = { path: string; params: URLSearchParams }

function read(): Route {
  return { path: location.pathname, params: new URLSearchParams(location.search) }
}

export function useRoute(): Route {
  const [route, setRoute] = useState<Route>(read)
  useEffect(() => {
    const onPop = () => setRoute(read())
    window.addEventListener("popstate", onPop)
    return () => window.removeEventListener("popstate", onPop)
  }, [])
  return route
}

export function replaceUrl(path: string) {
  history.replaceState(null, "", path)
}

import { useEffect, useRef } from "react"
import { useStore } from "@/lib/store"
import { replaceUrl, useRoute } from "./useRoute"

/**
 * Web Share Target: the manifest routes shares to GET /share?title=&text=&url=.
 * Read the shared text, clean the URL, and run the pipeline once.
 */
export function useShareTarget() {
  const route = useRoute()
  const s = useStore()
  const handled = useRef(false)
  useEffect(() => {
    if (handled.current) return
    if (route.path !== "/share" && !route.params.has("text")) return
    const text = [route.params.get("title"), route.params.get("text"), route.params.get("url")]
      .filter(Boolean)
      .join("\n")
      .trim()
    handled.current = true
    replaceUrl("/")
    if (!text) return
    s.dispatch({ type: "tab", tab: "plan" })
    void s.runFromText(text)
  }, [route, s])
}

import { useCallback, useState, type DragEvent } from "react"

/** Drag-and-drop of plain text or a .txt file onto an element. */
export function useDropText(onText: (text: string) => void) {
  const [over, setOver] = useState(false)
  const onDragOver = useCallback((e: DragEvent) => {
    e.preventDefault()
    setOver(true)
  }, [])
  const onDragLeave = useCallback(() => setOver(false), [])
  const onDrop = useCallback(
    async (e: DragEvent) => {
      e.preventDefault()
      setOver(false)
      const dt = e.dataTransfer
      const file = dt.files?.[0]
      if (file && (file.type.startsWith("text/") || file.name.endsWith(".txt"))) {
        onText(await file.text())
        return
      }
      const text = dt.getData("text/plain") || dt.getData("text/uri-list")
      if (text) onText(text)
    },
    [onText],
  )
  return { over, handlers: { onDragOver, onDragLeave, onDrop } }
}

