}

export function JourneyBuilder() {
  const s = useStore()
  const today = new Date().toISOString().slice(0, 10)
  const [date, setDate] = useState(today)
  const [legs, setLegs] = useState<Draft[]>([{ trainId: "RB 16", dep: "04:34", arr: "07:25" }])

  const complete = legs.every((l) => l.trainId && l.from && l.to && l.dep && l.arr)

  const submit = () => {
    const built: Leg[] = legs.map((l, i) => {
      const next = legs[i + 1]
      const leg: Leg = {
        trainId: l.trainId.trim(),
        from: { evaNumber: l.from!.evaNumber, name: l.from!.name, lat: l.from!.lat, lon: l.from!.lon },
        to: { evaNumber: l.to!.evaNumber, name: l.to!.name, lat: l.to!.lat, lon: l.to!.lon },
        plannedDeparture: iso(date, l.dep),
        plannedArrival: iso(date, l.arr),
      }
      if (next) {
        const mins = Math.round((new Date(iso(date, next.dep)).getTime() - new Date(iso(date, l.arr)).getTime()) / 60000)
        leg.transferMinutes = Math.max(0, mins)
      }
      return leg
    })
    const journey: Journey = { id: `manual-${Date.now().toString(36)}`, source: "manual", legs: built }
    void s.runJourney(journey)
  }

  return (
    <div className="space-y-3">
      <div>
        <label className="text-[11px] uppercase tracking-wide text-muted-foreground">Travel date</label>
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full rounded-lg border border-input bg-black/30 px-2.5 py-1.5 text-sm outline-none focus:border-ring" />
      </div>
      {legs.map((l, i) => (
        <div key={i} className="space-y-2 rounded-xl border border-border bg-black/20 p-3">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-muted-foreground">Train {i + 1}</span>
            {legs.length > 1 && (
              <button type="button" onClick={() => setLegs(legs.filter((_, j) => j !== i))} className="text-muted-foreground hover:text-foreground" aria-label="Remove train">
                <Trash2 className="size-4" />
              </button>
            )}
          </div>
          <input
            value={l.trainId}
            onChange={(e) => setLegs(legs.map((x, j) => (j === i ? { ...x, trainId: e.target.value } : x)))}
            placeholder="Train, e.g. ICE 1005"
            className="w-full rounded-lg border border-input bg-black/30 px-2.5 py-1.5 text-sm outline-none focus:border-ring"
          />
          <div className="grid grid-cols-2 gap-2">
            <StationField label="From" value={l.from} onPick={(st) => setLegs(legs.map((x, j) => (j === i ? { ...x, from: st } : x)))} />
            <StationField label="To" value={l.to} onPick={(st) => setLegs(legs.map((x, j) => (j === i ? { ...x, to: st } : x)))} />
            <div>
              <label className="text-[11px] uppercase tracking-wide text-muted-foreground">Departs</label>
              <input type="time" value={l.dep} onChange={(e) => setLegs(legs.map((x, j) => (j === i ? { ...x, dep: e.target.value } : x)))} className="w-full rounded-lg border border-input bg-black/30 px-2.5 py-1.5 text-sm outline-none focus:border-ring" />
            </div>
            <div>
              <label className="text-[11px] uppercase tracking-wide text-muted-foreground">Arrives</label>
              <input type="time" value={l.arr} onChange={(e) => setLegs(legs.map((x, j) => (j === i ? { ...x, arr: e.target.value } : x)))} className="w-full rounded-lg border border-input bg-black/30 px-2.5 py-1.5 text-sm outline-none focus:border-ring" />
            </div>
          </div>
        </div>
      ))}
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => {
            const last = legs[legs.length - 1]
            setLegs([...legs, { trainId: "", from: last.to, dep: last.arr, arr: last.arr }])
          }}
          className="inline-flex items-center gap-1.5 rounded-xl border border-border px-3 py-2 text-sm hover:bg-white/5"
        >
          <Plus className="size-4" /> Add a change
        </button>
        <button type="button" disabled={!complete || s.busy} onClick={submit} className="flex-1 rounded-xl bg-primary px-4 py-2 font-medium text-white disabled:opacity-50">
          Check my plan
        </button>
      </div>
    </div>
  )
}

import { animate } from "motion"
import { useEffect, useMemo, useRef, useState } from "react"
import type { Journey, LegDelay, Prediction } from "@/lib/contract"
import { rechain, transferBuffer } from "@/lib/chain"
import { pct, riskColour } from "@/lib/geo"
import { useReducedMotion } from "@/lib/motion"
import { useStore } from "@/lib/store"
import { LegCard } from "@/features/share-parser/components/LegCard"
import { WhyDisclosure } from "./WhyDisclosure"

/* ---------- headline count-up ---------- */
export function FailHeadline({ value, label = "Probability your plan fails" }: { value: number; label?: string }) {
  const still = useReducedMotion()
  const [shown, setShown] = useState(still ? value : 0)
  const prev = useRef(0)
  useEffect(() => {
    if (still) {
      setShown(value)
      return
    }
    const controls = animate(prev.current, value, { duration: 1.2, ease: "easeOut", onUpdate: (v) => setShown(v) })
    prev.current = value
    return () => controls.stop()
  }, [value, still])
  const colour = riskColour(value)
  return (
    <div className="rounded-2xl border border-border bg-black/30 p-4">
      <div className="text-xs uppercase tracking-wide text-muted-foreground">{label}</div>
      <div className="headline-number mt-1 text-6xl font-semibold" style={{ color: colour }}>
        {Math.round(shown * 100)}
        <span className="text-3xl">%</span>
      </div>
    </div>
  )
}

/* ---------- per-leg delay bars ---------- */
export function DelayBars({ leg }: { leg: LegDelay }) {
  const d = leg.distribution
  if (!d) return null
  const max = Math.max(...d.probs, 0.01)
  const colours = ["#34d399", "#a3e635", "#fbbf24", "#f87171", "#9ca3af"]
  return (
    <svg viewBox="0 0 220 64" className="mt-2 h-16 w-full" role="img" aria-label="Delay probability by bucket">
      {d.bins.map((bin, i) => {
        const p = d.probs[i] ?? 0
        const h = Math.max(2, (p / max) * 40)
        const x = 4 + i * 44
        return (
          <g key={bin}>
            <rect x={x} y={44 - h} width={36} height={h} rx={3} fill={colours[i] ?? "#999"} opacity={0.9} />
            <text x={x + 18} y={44 - h - 3} textAnchor="middle" fontSize="9" fill="#e5e5ea">
              {Math.round(p * 100)}%
            </text>
            <text x={x + 18} y={58} textAnchor="middle" fontSize="9" fill="#9a9aa8">
              {bin}
            </text>
          </g>
        )
      })}
    </svg>
  )
}

/* ---------- chain strip ---------- */
export function ChainStrip({ journey, prediction, missOverride }: { journey: Journey; prediction: Prediction; missOverride?: number[] }) {
  return (
    <div className="flex items-stretch gap-1 overflow-x-auto py-1">
      {journey.legs.map((leg, i) => {
        const last = i === journey.legs.length - 1
        const miss = missOverride?.[i] ?? prediction.legs[i]?.missProbability.value ?? 0
        const delay = prediction.legs[i]?.expectedDelayMinutes.value ?? 0
        const buffer = transferBuffer(journey, i)
        const left = Math.max(0, buffer - delay)
        return (
          <div key={i} className="flex items-center gap-1">
            <div className="rounded-lg border border-border bg-black/30 px-2 py-1.5 text-center">
              <div className="font-mono text-[11px] font-semibold">{leg.trainId}</div>
              <div className="text-[10px] text-muted-foreground">+{delay} min</div>
            </div>
            {!last && (
              <div className="flex flex-col items-center px-1 text-[10px]" title={`${buffer} min planned change`}>
                <div className="relative h-2.5 rounded-full bg-white/10" style={{ width: Math.min(96, 8 + buffer * 3) }}>
                  <div
                    className="absolute inset-y-0 left-0 rounded-full"
                    style={{ width: `${Math.round((left / Math.max(buffer, 1)) * 100)}%`, background: riskColour(miss) }}
                  />
                </div>
                <span style={{ color: riskColour(miss) }}>{miss >= 0.4 ? "missed?" : `${pct(miss)} miss`}</span>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

/* ---------- buffer slider ---------- */
export function BufferSlider({ journey, prediction }: { journey: Journey; prediction: Prediction }) {
  const s = useStore()
  const result = useMemo(() => rechain(journey, prediction, s.bufferExtra), [journey, prediction, s.bufferExtra])
  if (journey.legs.length < 2) return null
  return (
    <div className="rounded-xl border border-border bg-black/30 p-3">
      <div className="flex items-center justify-between text-sm">
        <span>
          What if I had <b>+{s.bufferExtra} min</b> at every change?
        </span>
        <span className="font-mono" style={{ color: riskColour(result.planFail) }}>
          {pct(result.planFail)}
        </span>
      </div>
      <input
        type="range"
        min={0}
        max={60}
        step={5}
        value={s.bufferExtra}
        onChange={(e) => s.dispatch({ type: "buffer", minutes: Number(e.target.value) })}
        className="mt-2 w-full accent-[#8b8bff]"
        aria-label="Extra minutes at each change"
      />
      <p className="mt-1 text-[11px] text-muted-foreground">Re-chained in your browser with the same transfer math as the forecast.</p>
    </div>
  )
}

/* ---------- the panel ---------- */
export function ForecastPanel() {
  const s = useStore()
  const journey = s.journey
  const prediction = s.prediction
  if (!journey) return null
  if (!prediction)
    return (
      <div className="space-y-3">
        <div className="h-24 animate-pulse rounded-2xl bg-white/5" />
        <p className="text-sm text-muted-foreground">Forecasting each train…</p>
      </div>
    )
  const live = s.bufferExtra > 0 ? rechain(journey, prediction, s.bufferExtra) : null
  return (
    <div className="space-y-3">
      <FailHeadline value={live ? live.planFail : prediction.planFailProbability.value} />
      <WhyDisclosure item={prediction.planFailProbability} label="Why this number?" />
      <ChainStrip journey={journey} prediction={prediction} missOverride={live?.legs} />
      <div className="space-y-2">
        {journey.legs.map((leg, i) => {
          const d = prediction.legs[i]
          if (!d) return null
          const q = d.quantiles
          return (
            <LegCard key={i} leg={leg} index={i} active={s.selectedLeg === i} delay={d} onSelect={(j) => s.dispatch({ type: "selectLeg", index: s.selectedLeg === j ? null : j })}>
              <div className="mt-2 flex items-baseline justify-between text-sm">
                <span>
                  <b>+{d.expectedDelayMinutes.value} min</b>
                  {q && <span className="text-muted-foreground"> · likely {q.p10}–{q.p90}</span>}
                </span>
                {i < journey.legs.length - 1 && (
                  <span className="text-xs" style={{ color: riskColour(live?.legs[i] ?? d.missProbability.value) }}>
                    {pct(live?.legs[i] ?? d.missProbability.value)} chance to miss the change
                  </span>
                )}
              </div>
              <DelayBars leg={d} />
              <div className="mt-1 flex flex-wrap gap-3">
                <WhyDisclosure item={d.expectedDelayMinutes} label="Why this delay?" />
                {i < journey.legs.length - 1 && <WhyDisclosure item={d.missProbability} label="Why this change?" />}
              </div>
            </LegCard>
          )
        })}
      </div>
      <BufferSlider journey={journey} prediction={prediction} />
      <p className="text-[11px] text-muted-foreground">
        Model: <span className="font-mono">{prediction.modelId}</span>
        {prediction.modelId.startsWith("mock") && " · prior only, the fine-tuned model server is offline"}
      </p>
    </div>
  )
}

import { AlertTriangle, CheckCircle2, CloudLightning, Home, Route, Share2, Umbrella } from "lucide-react"
import { useMemo } from "react"
import type { Recommendation, Verdict } from "@/lib/contract"
import { fmtTime, pct, riskColour } from "@/lib/geo"
import { useStore } from "@/lib/store"
import { cn } from "@/lib/utils"
import { WhyDisclosure } from "@/features/delay-prediction/components/WhyDisclosure"

const VERDICT: Record<Verdict, { label: string; Icon: typeof Umbrella; colour: string }> = {
  good: { label: "Clear skies — keep your plan", Icon: CheckCircle2, colour: "#34d399" },
  "add-buffer": { label: "Showers likely — add buffer", Icon: Umbrella, colour: "#fbbf24" },
  "take-alternative": { label: "Storm warning — take the earlier train", Icon: CloudLightning, colour: "#f87171" },
}

function minus(iso: string, minutes: number): string {
  return new Date(new Date(iso).getTime() - minutes * 60000).toISOString()
}

/* ---------- leave home by ---------- */
export function LeaveHomeBy({ rec }: { rec: Recommendation }) {
  const s = useStore()
  const journey = s.journey
  if (!journey) return null
  const chosen = rec.chosenDeparture ?? (rec.verdict === "take-alternative" && rec.alternative ? rec.alternative.legs[0].plannedDeparture : journey.legs[0].plannedDeparture)
  const leaveBy = useMemo(() => minus(chosen, s.doorToStationMin + 5), [chosen, s.doorToStationMin])
  return (
    <div className="rounded-xl border border-border bg-black/30 p-3">
      <div className="flex items-center gap-2 text-sm font-medium">
        <Home className="size-4 text-muted-foreground" /> Leave home by <span className="ml-auto font-mono text-lg">{fmtTime(leaveBy)}</span>
      </div>
      <p className="mt-1 text-xs text-muted-foreground">
        {s.doorToStationMin} min door to {journey.legs[0].from.name}, 5 min to find the platform, {rec.verdict === "take-alternative" ? "the earlier" : "your"} train at {fmtTime(chosen)}.
      </p>
      <label className="mt-2 flex items-center gap-2 text-xs text-muted-foreground">
        Door → station
        <input
          type="range"
          min={5}
          max={90}
          step={5}
          value={s.doorToStationMin}
          onChange={(e) => s.dispatch({ type: "door", minutes: Number(e.target.value) })}
          className="flex-1 accent-[#8b8bff]"
          aria-label="Minutes from door to the first station"
        />
        <span className="w-12 text-right font-mono">{s.doorToStationMin} min</span>
      </label>
    </div>
  )
}

/* ---------- missed connection / re-route ---------- */
