function gradient(colour: string, t: number): maplibregl.ExpressionSpecification {
  const stop = Math.max(0, Math.min(1, t))
  const edge = Math.min(1, stop + 0.0005)
  return ["interpolate", ["linear"], ["line-progress"], 0, colour, stop, colour, edge, "rgba(0,0,0,0)", 1, "rgba(0,0,0,0)"]
}

input.new_string:
const CLEAR = "rgba(0,0,0,0)"

/** Gradient that paints the first `t` of the line in `colour`; stops must be strictly ascending. */
function gradient(colour: string, t: number): maplibregl.ExpressionSpecification {
  if (t <= 0) return ["interpolate", ["linear"], ["line-progress"], 0, CLEAR, 1, CLEAR]
  if (t >= 0.999) return ["interpolate", ["linear"], ["line-progress"], 0, colour, 1, colour]
  const edge = Math.min(0.9995, t + 0.0005)
  return ["interpolate", ["linear"], ["line-progress"], 0, colour, t, colour, edge, CLEAR, 1, CLEAR]
}

